#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
#
# Rebuilds every figure and derived-statistics JSON used in the
# cache-policy evaluation report from already-committed benchmark
# results -- no sweeps are re-run. Does NOT build the PDF report: the
# checked-in report/cache_policy_evaluation_report.pdf is the final
# submitted document and is not regenerated by this repository.
#
# Must be run from the repository root, with `lmcache` importable (this
# script sets PYTHONPATH=. itself) and matplotlib installed -- see
# benchmarks/cache_policy/environment.yml, requirements-figures.txt, or
# the Dockerfile for how to get there.
#
# Usage:
#   ./benchmarks/cache_policy/reproduce_figures.sh

set -euo pipefail

export PYTHONHASHSEED=0
export PYTHONPATH=.
export MPLBACKEND=Agg

python benchmarks/cache_policy/compare_admission_vs_lfu.py \
  --input benchmarks/cache_policy/results/admission_control/multiseed_sweep_raw.json \
  --output benchmarks/cache_policy/results/admission_control/admission_vs_lfu_paired.json

python benchmarks/cache_policy/report/generate_figures.py \
  -o benchmarks/cache_policy/report/figures
